    for color in range(9):
        if color == 8:
            continue
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == color:
                    all_non_bg.append((r, c))

    if not all_non_bg:
        return output

    # Find region bbox
    min_r, max_r = min(p[0] for p in all_non_bg), max(p[0] for p in all_non_bg)
    min_c, max_c = min(p[1] for p in all_non_bg), max(p[1] for p in all_non_bg)

    # For each region, apply the rule
    visited = [[False] * cols for _ in range(rows)]

